theorem my_favorite_theorem : 
  let a : ℝ := 8
  let b : ℝ := 15
  let c : ℝ := Real.sqrt (a^2 + b^2)
  let O : ℝ × ℝ := (0, 0)
  let A : ℝ × ℝ := (a, 0)  
  let B : ℝ × ℝ := (0, b)
  let M : ℝ × ℝ := ((a + 0) / 2, (0 + b) / 2)  -- midpoint of hypotenuse AB
  let median_length : ℝ := Real.sqrt ((M.1 - O.1)^2 + (M.2 - O.2)^2)
  c = 17 ∧ median_length = 17/2

